'use server'

import { updateTag } from 'next/cache'

import { insertPost } from '@/lib/posts'

function requiredText(formData: FormData, field: string): string {
  const value = formData.get(field)

  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${field} is required`)
  }

  return value.trim()
}

export async function createPost(formData: FormData): Promise<void> {
  await insertPost({
    title: requiredText(formData, 'title'),
    content: requiredText(formData, 'content'),
  })

  // Immediately expire the cached list. Unlike stale-while-revalidate, updateTag
  // makes the next read wait for fresh data and provides read-your-own-writes.
  updateTag('posts')
}
import { unstable_cache } from 'next/cache'

import { createPost } from '@/app/actions'
import { getAllPosts } from '@/lib/posts'

const getPosts = unstable_cache(getAllPosts, ['posts'], {
  tags: ['posts'],
})

export default async function Home() {
  const posts = await getPosts()

  return (
    <main>
      <h1>Posts</h1>

      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <article>
              <h2>{post.title}</h2>
              <p>{post.content}</p>
            </article>
          </li>
        ))}
      </ul>

      <h2>Create a post</h2>
      <form action={createPost}>
        <p>
          <label htmlFor="title">Title</label>{' '}
          <input id="title" name="title" required />
        </p>
        <p>
          <label htmlFor="content">Content</label>{' '}
          <textarea id="content" name="content" required />
        </p>
        <button type="submit">Create post</button>
      </form>
    </main>
  )
}
import 'server-only'

export type Post = {
  id: number
  title: string
  content: string
}

type PostStore = {
  nextId: number
  posts: Post[]
}

const globalForPosts = globalThis as typeof globalThis & {
  postStore?: PostStore
}

// Keep the example data available across module reloads in development.
const postStore = (globalForPosts.postStore ??= {
  nextId: 2,
  posts: [
    {
      id: 1,
      title: 'Welcome',
      content: 'Create a post using the form below.',
    },
  ],
})

export async function getAllPosts(): Promise<Post[]> {
  return postStore.posts.map((post) => ({ ...post }))
}

export async function insertPost(input: {
  title: string
  content: string
}): Promise<Post> {
  const post = { id: postStore.nextId++, ...input }

  postStore.posts.push(post)

  return { ...post }
}
